def compute(vars):
    values = {
        "June 30, 2019": vars["v1"],
        "June 24, 2018": vars["v2"],
        "June 25, 2017": vars["v3"],
    }

    highest_year = max(values, key=values.get)

    return {
        "value": highest_year,
        "trace": {
            "values": values,
            "highest_value": values[highest_year],
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None,
            },
        },
    }
